package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Every tag ever used on the sheet's claims, sorted: kept even once no claim carries it. */
public class RespondWithTags {
    public void respond(@PathVariable("sheetId") String sheetId, ClaimRepository repository,
            ObjectResponse<List<String>> response) {
        response.send(repository.tagsUsed(sheetId.trim()));
    }
}
import { SheetBody } from '../../slots/defs/sheet';
import { usePeople } from '../people/people';
import { sheetTagSum, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { useClaims, useTagsUsed } from './claims';

/** The sheet's due-total per tag, for every tag ever used on it: the dues of the claims that count which carry it
 *  (a claim with two tags counts in both; see sheetTagSum). */
function TagTotals({ sheetId }: { sheetId: string; user: string }) {
  const tags = useTagsUsed(sheetId).data ?? [];
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  if (tags.length === 0) return null;
  return (
    <p>
      Due by tag{' '}
      {[...tags].sort().map((tag) => (
        <span key={tag}>
          {tag} <strong data-testid={`tag-${tag}-due-total`}>{sheetTagSum(people, claims, rates, today, floor, late, tag)}</strong>{' '}
        </span>
      ))}
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 21.6, Component: TagTotals });
